'use strict';const M=SpeedDialModel,U=OmniUI,$=id=>document.getElementById(id);let state,selected=null,editing=null,moving=null,pending=null,epoch=0;window.OMNI_PREVIEW=!window.omnibloomHost;const textErrors={INVALID_URL:'Use a complete HTTP or HTTPS address without spaces or a password.',INVALID_TILE:'Enter a site name of up to 64 characters.',STORAGE_FULL:'Storage is full. No changes were saved.',STALE_STATE:'Tiles changed in another window. Reload and try again.',LIMIT_REACHED:'You can keep up to 24 sites.',HOST_UNAVAILABLE:'Opening sites needs the browser host.'};function error(e){return textErrors[e.code||e.message]||'Could not finish that action. Your saved tiles are unchanged.'}function el(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e}function id(){return 'site-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8)}
function draw(focusId){const tiles=pending||state.tiles;$('tiles').replaceChildren();for(const t of tiles){const card=el('article','tile'+(moving===t.id?' selected':'')),open=el('button','open');open.dataset.id=t.id;open.setAttribute('aria-label',(moving?'Move ':'Open ')+t.title);if(t.icon){const img=el('img','favicon');img.alt='';img.src='data:'+t.icon.mime+';base64,'+t.icon.base64;img.onerror=()=>img.replaceWith(el('span','initial',t.title.slice(0,1).toUpperCase()));open.append(img)}else open.append(el('span','initial',t.title.slice(0,1).toUpperCase()));open.append(el('h2','',t.title),el('small','',new URL(t.url).hostname));open.onclick=()=>moving?saveOrder():navigate(t);const more=el('button','','More');more.setAttribute('aria-label','More options for '+t.title);more.disabled=!!moving;more.onclick=()=>{selected=t.id;$('action-title').textContent=t.title;U.modal('actions')};card.append(open,more);$('tiles').append(card)}if(!tiles.length)$('tiles').append(el('p','empty','No sites yet. Add your first favourite.'));$('add').disabled=!!moving||tiles.length>=M.MAX;$('reorder').hidden=!moving;if(focusId)U.focus(document.querySelector('[data-id="'+focusId+'"]'))}
async function navigate(t){try{await U.request('navigation.open',{url:M.url(t.url)},()=>({accepted:true}));U.notify(window.OMNI_PREVIEW?'Preview: site selected.':'Opening site.')}catch(e){U.notify(error(e))}}
function openEditor(t){editing=t?.id||null;$('editor-title').textContent=t?'Edit site':'Add a site';$('title').value=t?.title||'';$('url').value=t?.url||'';$('editor-error').textContent='';U.modal('editor')}
function persist(tiles){state=M.commit(localStorage,state.revision,tiles);epoch++;draw();return state}
$('add').onclick=()=>openEditor(null);$('edit').onclick=()=>{const t=state.tiles.find(t=>t.id===selected);U.close();openEditor(t)};$('save').onclick=async()=>{try{const existing=state.tiles.find(t=>t.id===editing),newId=editing||id(),input={title:$('title').value,url:$('url').value,icon:existing&&new URL(existing.url).origin===new URL(M.url($('url').value)).origin?existing.icon:null};const tiles=M.edit(state,input,newId);persist(tiles);U.close();draw(newId);U.notify('Site saved.');const expectedEpoch=epoch;try{const result=await U.request('siteIcon.get',{origin:new URL(input.url).origin},()=>null);if(result&&epoch===expectedEpoch){const cached=M.icon(result),updated=state.tiles.map(t=>t.id===newId?{...t,icon:cached}:t);persist(updated);draw(newId)}}catch(_){/* Initial remains when the icon cache is unavailable. */}}catch(e){$('editor-error').textContent=error(e)}};
$('remove').onclick=()=>{try{persist(state.tiles.filter(t=>t.id!==selected));U.close();U.focus($('add'));U.notify('Site removed.')}catch(e){U.notify(error(e))}};
$('move').onclick=()=>{moving=selected;pending=state.tiles.slice();U.close();draw(moving);U.notify('Move '+state.tiles.find(t=>t.id===moving).title+'. Cross saves; Circle cancels.')};function cancelOrder(){const old=moving;moving=null;pending=null;draw(old);U.notify('Order unchanged.')}function saveOrder(){try{const old=moving;state=M.commit(localStorage,state.revision,pending);epoch++;moving=null;pending=null;draw(old);U.notify('Order saved.')}catch(e){U.notify(error(e))}}$('save-order').onclick=saveOrder;$('cancel-order').onclick=cancelOrder;
window.handlePageController=a=>{if(!moving)return false;if(a==='circle'){cancelOrder();return true}if(a==='cross'&&document.activeElement.matches('.open')){saveOrder();return true}if(['left','right','up','down','l1','r1'].includes(a)&&document.activeElement.matches('.open')){const columns=getComputedStyle($('tiles')).gridTemplateColumns.split(' ').length,delta={left:-1,right:1,up:-columns,down:columns,l1:-1,r1:1}[a],from=pending.findIndex(t=>t.id===moving),to=from+delta;if(to>=0&&to<pending.length){pending=M.move(pending,moving,to);draw(moving);U.notify('Position '+(to+1)+' of '+pending.length)}return true}return false};
$('reset').onclick=()=>{try{localStorage.removeItem(M.KEY);location.reload()}catch(_){U.notify('Storage is unavailable.')}};function load(){try{state=M.load(localStorage);$('failure').hidden=true;draw();U.focus($('add'))}catch(_){$('failure').hidden=false;$('add').disabled=true;U.focus($('reset'))}}window.addEventListener('storage',e=>{if(e.key===M.KEY){epoch++;moving=null;pending=null;U.close();load();U.notify('Tiles updated in another window.')}});load();
